    /** Lock name where PIN was last used */
    last_used_lock?: string;
    /** Per-lock sync status */
    locks: SlotCardLockStatus[];
    name: string;
    /** The PIN value (actual or masked) */
    pin: string | null;
    /** PIN length when masked */
    pin_length?: number;
    /**
