 * subscription, and assertions read the shadow DOM.
 */

interface SlotCard extends HTMLElement {
    hass: HomeAssistant;
    setConfig: (config: Record<string, unknown>) => void;
    updateComplete: Promise<boolean>;
}

const PIN = '4815';

describe('slot card, rendered', () => {
    let card: SlotCard;
