            expect(deepTemplateStrings(tmpl)).toContain('Full history');
            for (const h of collectHandlers(tmpl)) h();
            expect(dispatched).toHaveLength(1);
            expect(dispatched[0].detail).toEqual({
                entityId: 'event.lcm_slot_1_pin_used'
            });
        });
""")
