                () => {
                    throw new Error('recorder not loaded');
                }
            );
            (root.querySelector('.event-row') as HTMLElement).click();
            await settle();
            expect(root.querySelector('.uses-message')?.textContent).toContain("Couldn't read the history");
        });
    });

