attachment.snippet:
24	    target: string;
25	    /** Display name of the target, falling back to its entity ID */
26	    targetName: string;
27	    /** When the use was recorded (ISO timestamp, the event entity's state) */
28	    when: string;
29	}
30	
31	/** A state in Home Assistant's compressed history format. */
32	export interface CompressedState {
33	    a?: Record<string, unknown>;
34	    s: string;
35	}
36	
37	export type HistoryResponse = Record<string, CompressedState[] | undefined>;
38	
39	const OPERATION_LABELS: Record<string, string> = {
40	    lock: 'Locked',
41	    unlock: 'Unlocked'
42	};
43	
44	/**
45	 * The history stream for one event entity, attributes included.
46	 *
47	 * A stream rather than a one-off read: Home Assistant sends what the recorder
48	 * holds, then the states it had not yet committed, then every new state as
49	 * it happens. A one-off read misses uses still waiting on the recorder's next
50	 * commit, and every use after it.
51	 */
52	export function buildCredentialUsesStream(
53	    eventEntityId: string,
54	    now: Date = new Date()
55	): { [key: string]: unknown; type: string } {
56	    const start = new Date(now.getTime() - CREDENTIAL_USE_WINDOW_DAYS * 24 * 60 * 60 * 1000);
57	    return {
58	        entity_ids: [eventEntityId],
59	        include_start_time_state: false,
60	        minimal_response: false,
61	        no_attributes: false,
62	        // Every state, not only those whose state changed. The entity also
63	        // writes attribute-only states (its event_types move as locks are
64	        // probed), which repeat the last use's time; `mergeUseRows` keys
65	        // rows by time, so each use is still listed once.
66	        significant_changes_only: false,
67	        start_time: start.toISOString(),
68	        type: 'history/stream'
69	    };
70	}
71	
72	/** One message on the history stream. */
73	export interface HistoryStreamMessage {
74	    states?: HistoryResponse;
75	}
76	
77	/**
78	 * Whether a recorded state is a use.
79	 *
80	 * A state that is not a timestamp (`unknown`, `unavailable`) is not, and
81	 * neither is one recorded before 6.0, whose payload named no `target`.
82	 */
83	function isUse(row: CompressedState): boolean {
84	    return !Number.isNaN(Date.parse(row.s)) && typeof row.a?.target === 'string';
85	}
86	
87	/**
88	 * Fold rows from the stream into the rows kept, holding only what is listed.
89	 *
90	 * Keeps the newest `CREDENTIAL_USE_LIMIT` uses, one row per use time (a later
91	 * row for the same time wins), so the kept rows never grow past what the
92	 * card shows however long it stays open.
93	 */
94	export function mergeUseRows(
95	    kept: CompressedState[],
96	    incoming: CompressedState[]
97	): CompressedState[] {
98	    const byTime = new Map<string, CompressedState>();
99	    for (const row of [...kept, ...incoming]) {
100	        if (isUse(row)) byTime.set(row.s, row);
101	    }
102	    return [...byTime.values()]
103	        .sort((a, b) => Date.parse(b.s) - Date.parse(a.s))
104	        .slice(0, CREDENTIAL_USE_LIMIT);
105	}
106	
107	/**
108	 * Turn the history response into uses, newest first.
109	 *
110	 * Only uses are listed (see `isUse`). A restart writes the last use's state
111	 * again, so uses are keyed by their time and each is listed once.
112	 *
113	 * Only the target is looked up. The source can be a keypad entity whose state
114	 * is the code that was typed, so it is never read.
115	 */
116	export function parseCredentialUses(
117	    response: HistoryResponse | undefined,
118	    eventEntityId: string,
119	    states: HomeAssistant['states'] = {}
120	): CredentialUse[] {
121	    const byTime = new Map<string, CredentialUse>();
122	    const uses = (response?.[eventEntityId] ?? []).filter(isUse);
123	    for (const row of uses) {
124	        const attributes = row.a ?? {};
125	        const target = attributes.target as string;
126	        const friendlyName = states[target]?.attributes?.friendly_name;
127	        byTime.set(row.s, {
128	            credentialType: String(attributes.credential_type ?? attributes.event_type ?? ''),
129	            operation: String(attributes.operation ?? 'unknown'),
130	            target,
131	            targetName: typeof friendlyName === 'string' && friendlyName ? friendlyName : target,
132	            when: row.s
133	        });
134	    }
135	    return [...byTime.values()]
136	        .sort((a, b) => Date.parse(b.when) - Date.parse(a.when))
137	        .slice(0, CREDENTIAL_USE_LIMIT);
138	}
139	
140	/**
141	 * One line saying what was used and, when the device said, what it did.
142	 *
143	 * `formatKind` turns a kind into its translated label (the event entity's
144	 * `event_type` translations), so the card names a kind the way the entity's
145	 * own history does.
146	 */
147	export function describeCredentialUse(
148	    use: CredentialUse,
149	    formatKind: (kind: string) => string = (kind) => kind
150	): string {
151	    const kind = formatKind(use.credentialType);
152	    const operation = OPERATION_LABELS[use.operation];
153	    return operation ? `${kind} · ${operation}` : kind;
154	}

