attachment.snippet:
19	    /** Kind of credential presented: `pin`, `rfid`, `fingerprint`, ... */
20	    credentialType: string;
21	    /** What the device did: `unlock`, `lock` or `unknown` */
22	    operation: string;
23	    /** Entity the credential was used against */
24	    target: string;
25	    /** Display name of the target, falling back to its entity ID */
26	    targetName: string;
27	    /** When the use was recorded (International Organization for Standardization (ISO) 8601 timestamp, the event entity's state) */
28	    when: string;
29	}
30	
31	/** A state in Home Assistant's compressed history format. */
32	export interface CompressedState {
33	    a?: Record<string, unknown>;
34	    s: string;
35	}
36	
37	type HistoryStates = Record<string, CompressedState[] | undefined>;
38	
39	const OPERATION_LABELS: Record<string, string> = {
40	    lock: 'Locked',
41	    unlock: 'Unlocked'
42	};
43	
44	/**
45	 * The history stream for one event entity, attributes included.
46	 *
47	 * A stream rather than a one-off read: Home Assistant sends what the recorder
48	 * holds, then the states it had not yet committed, then every new state as
49	 * it happens. A one-off read misses uses still waiting on the recorder's next
50	 * commit, and every use after it.
51	 */
52	export function buildCredentialUsesStream(
53	    eventEntityId: string,
54	    now: Date = new Date()
55	): { [key: string]: unknown; type: string } {
56	    const start = new Date(now.getTime() - CREDENTIAL_USE_WINDOW_DAYS * 24 * 60 * 60 * 1000);
57	    return {
58	        entity_ids: [eventEntityId],
59	        include_start_time_state: false,
60	        minimal_response: false,
61	        no_attributes: false,
62	        // Every use moves the state to its own time, so state changes are
63	        // every use; the entity's attribute-only writes (its event_types
64	        // move as locks are probed) are left out.
65	        significant_changes_only: true,
66	        start_time: start.toISOString(),
67	        type: 'history/stream'
68	    };
69	}
70	
71	/** One message on the history stream. */
72	export interface HistoryStreamMessage {
73	    states?: HistoryStates;
74	}
75	
76	/**
77	 * Whether a recorded state is a use.
78	 *
79	 * A state that is not a timestamp (`unknown`, `unavailable`) is not, and
80	 * neither is one recorded before 6.0, whose payload named no `target`.
81	 */
82	function isUse(row: CompressedState): boolean {
83	    return !Number.isNaN(Date.parse(row.s)) && typeof row.a?.target === 'string';
84	}
85	
86	/**
87	 * Fold rows from the stream into the rows kept, holding only what is listed.
88	 *
89	 * Keeps the newest `CREDENTIAL_USE_LIMIT` uses, newest first, one row per
90	 * use time (a restart writes the last use's state again; the later row
91	 * wins), so the kept rows never grow past what the card shows however long
92	 * it stays open.
93	 */
94	export function mergeUseRows(
95	    kept: CompressedState[],
96	    incoming: CompressedState[]
97	): CompressedState[] {
98	    const byTime = new Map<string, CompressedState>();
99	    for (const row of [...kept, ...incoming]) {
100	        if (isUse(row)) byTime.set(row.s, row);
101	    }
102	    return [...byTime.values()]
103	        .sort((a, b) => Date.parse(b.s) - Date.parse(a.s))
104	        .slice(0, CREDENTIAL_USE_LIMIT);
105	}
106	
107	/**
108	 * Turn the kept rows (`mergeUseRows`) into uses, naming each target.
109	 *
110	 * Only the target is looked up. The source can be a keypad entity whose state
111	 * is the code that was typed, so it is never read.
112	 */
113	export function toCredentialUses(
114	    rows: CompressedState[],
115	    states: HomeAssistant['states'] = {}
116	): CredentialUse[] {
117	    return rows.map((row) => {
118	        const attributes = row.a ?? {};
119	        const target = attributes.target as string;
120	        const friendlyName = states[target]?.attributes?.friendly_name;
121	        return {
122	            credentialType: String(attributes.credential_type ?? attributes.event_type ?? ''),
123	            operation: String(attributes.operation ?? 'unknown'),
124	            target,
125	            targetName: typeof friendlyName === 'string' && friendlyName ? friendlyName : target,
126	            when: row.s
127	        };
128	    });
129	}
130	
131	/**
132	 * One line saying what was used and, when the device said, what it did.
133	 *
134	 * `formatKind` turns a kind into its translated label (the event entity's
135	 * `event_type` translations), so the card names a kind the way the entity's
136	 * own history does.
137	 */
138	export function describeCredentialUse(
139	    use: CredentialUse,
140	    formatKind: (kind: string) => string = (kind) => kind
141	): string {
142	    const kind = formatKind(use.credentialType);
143	    const operation = OPERATION_LABELS[use.operation];
144	    return operation ? `${kind} · ${operation}` : kind;
145	}

